const FORMAT = 'survey-photo-static-v1';
const SCOPE = new URL(self.registration.scope);
const PREFIX = `${FORMAT}:${SCOPE.href}:`;
const BUILD_PATTERN = /^[a-f0-9]{20}$/;
const cacheName = buildId => `${PREFIX}${buildId}`;
const metadataURL = buildId => new URL(`__offline_cache__/${buildId}`, SCOPE).href;
const assetURL = asset => new URL(asset.path, SCOPE).href;

function validManifest(manifest, buildId) {
  return manifest?.format === FORMAT && manifest.buildId === buildId && BUILD_PATTERN.test(buildId) &&
    typeof manifest.version === 'string' && Array.isArray(manifest.assets) && manifest.assets.length > 0 &&
    manifest.assets.every(asset => typeof asset.path === 'string' && /^[a-f0-9]{64}$/.test(asset.sha256) &&
      (asset.path === 'index.html' || asset.path.startsWith(`assets/${buildId}/`)) &&
      !asset.path.includes('..') && !asset.path.includes('?') && !asset.path.includes('#'));
}

async function verifiedResponse(url, expectedHash) {
  const response = await fetch(new Request(url, { cache: 'no-store', credentials: 'same-origin', redirect: 'error' }));
  if (!response.ok || response.type === 'opaque') throw new Error('必要なアプリ資材を取得できませんでした。');
  const bytes = await response.clone().arrayBuffer();
  const hash = [...new Uint8Array(await crypto.subtle.digest('SHA-256', bytes))].map(value => value.toString(16).padStart(2, '0')).join('');
  if (hash !== expectedHash) throw new Error('アプリ資材の版が揃っていません。通信できる場所で再度準備してください。');
  return response;
}

async function cachedManifest(buildId) {
  if (!BUILD_PATTERN.test(buildId) || !(await caches.keys()).includes(cacheName(buildId))) return null;
  const cache = await caches.open(cacheName(buildId));
  const record = await cache.match(metadataURL(buildId));
  if (!record) return null;
  try {
    const manifest = await record.json();
    return validManifest(manifest, buildId) ? manifest : null;
  } catch { return null; }
}

async function offlineStatus(buildId = MANIFEST.buildId) {
  const manifest = await cachedManifest(buildId);
  let cachedCount = 0;
  if (manifest) {
    const cache = await caches.open(cacheName(buildId));
    for (const asset of manifest.assets) if (await cache.match(assetURL(asset))) cachedCount++;
  }
  return {
    ready: Boolean(manifest && cachedCount === manifest.assets.length),
    version: manifest?.version ?? '', buildId, assetCount: manifest?.assets.length ?? 0, cachedCount,
    workerVersion: MANIFEST.version, workerBuildId: MANIFEST.buildId,
  };
}

async function prepareAssets({ installing = false } = {}) {
  if (!validManifest(MANIFEST, MANIFEST.buildId)) throw new Error('圏外対応のビルド情報が不正です。');
  const name = cacheName(MANIFEST.buildId);
  const cache = await caches.open(name);
  try {
    for (const asset of MANIFEST.assets) {
      const url = assetURL(asset);
      // An active worker can repair a missing asset without discarding the other files.
      if (!installing && await cache.match(url)) continue;
      await cache.put(url, await verifiedResponse(url, asset.sha256));
    }
    await cache.put(metadataURL(MANIFEST.buildId), new Response(JSON.stringify(MANIFEST), { headers: { 'Content-Type': 'application/json' } }));
    return await offlineStatus();
  } catch (error) {
    if (installing) await caches.delete(name);
    else await cache.delete(metadataURL(MANIFEST.buildId));
    throw error;
  }
}

async function notify(type) {
  const clients = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
  for (const client of clients) {
    if (client.url.startsWith(SCOPE.href)) client.postMessage({ type, buildId: MANIFEST.buildId, version: MANIFEST.version });
  }
}

self.addEventListener('install', event => {
  // Updates stay waiting. Existing workers and their caches remain available on failure.
  event.waitUntil(prepareAssets({ installing: true }));
});

self.addEventListener('activate', event => {
  // Retain old version caches: an already open old HTML keeps importing its versioned URLs.
  // Never clear IndexedDB, claim clients, or reload a page here.
  event.waitUntil(notify('OFFLINE_ACTIVATED'));
});

self.addEventListener('message', event => {
  const port = event.ports?.[0];
  if (!port) return;
  event.waitUntil((async () => {
    try {
      if (event.data?.type === 'GET_OFFLINE_STATUS') port.postMessage(await offlineStatus(event.data.buildId));
      else if (event.data?.type === 'PREPARE_OFFLINE') port.postMessage(await prepareAssets());
      else if (event.data?.type === 'ACTIVATE_UPDATE') {
        port.postMessage({ accepted: true });
        await self.skipWaiting();
      } else port.postMessage({ error: '未対応の圏外操作です。' });
    } catch (error) { port.postMessage({ error: error.message }); }
  })());
});

async function versionedAsset(request, buildId, canonicalURL) {
  const manifest = await cachedManifest(buildId);
  const asset = manifest?.assets.find(item => assetURL(item) === canonicalURL);
  if (!asset) {
    // Exact version URL only. Never substitute assets from a different build.
    return fetch(request);
  }
  const cache = await caches.open(cacheName(buildId));
  const hit = await cache.match(canonicalURL);
  if (hit) return hit;
  try {
    const response = await verifiedResponse(canonicalURL, asset.sha256);
    await cache.put(canonicalURL, response.clone());
    return response;
  } catch {
    return new Response('この版のアプリ資材を読み込めません。通信できる場所で圏外の準備をやり直してください。', { status: 503, headers: { 'Content-Type': 'text/plain; charset=utf-8' } });
  }
}

self.addEventListener('fetch', event => {
  const request = event.request;
  const url = new URL(request.url);
  if (request.method !== 'GET' || url.origin !== SCOPE.origin || !url.pathname.startsWith(SCOPE.pathname)) return;
  const relative = url.pathname.slice(SCOPE.pathname.length);
  if (request.mode === 'navigate' && (relative === '' || relative === 'index.html')) {
    event.respondWith(versionedAsset(request, MANIFEST.buildId, new URL('index.html', SCOPE).href));
    return;
  }
  const match = /^assets\/([a-f0-9]{20})\//.exec(relative);
  if (match) {
    url.search = ''; url.hash = '';
    event.respondWith(versionedAsset(request, match[1], url.href));
  }
});
